      }
    ],
    "lacunas": [
      "O término novo e, portanto, sua diferença em relação a D10 dependem de precedências não fornecidas."
    ],
    "motivo": "A referência é D10, mas não há suporte para calcular o término após o aviso nem para afirmar a direção da variação.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa declara orçamento de R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O preço da extensão, se houver, não tem valor nem teto definido.",
      "A falta das precedências impede determinar se haverá extensão."
    ],
    "motivo": "O aviso acrescenta R$ 200,00 e mantém o valor fixo do apoio; eventual extensão tem preço não negativo, mas não quantificado.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A magnitude depende do preço de eventual extensão, que não foi definido."
    ],
    "motivo": "A cobrança única de R$ 200,00 não incluída na linha base garante aumento; eventual preço de extensão não pode ser negativo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base permite fixar D10 e R$ 5.000,00. Sem as precedências, não é possível quantificar o término novo ou saber se haverá extensão. O custo aumenta ao menos R$ 200,00, mas o eventual preço de extensão não foi definido."
}

